import re
import urllib.request
import json

# Constants
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'

def task_func(API_URL):
    """
    Get the public IP address of the current host from an API.

    Parameters:
    API_URL (str): The URL of the API endpoint that returns the public IP

    Returns:
    str: The public IP address

    Raises:
    ValueError: If the API request fails or the response is invalid
    """
    try:
        with urllib.request.urlopen(API_URL, timeout=10) as response:
            data = response.read().decode('utf-8')

            # Try to parse as JSON first (common API response format)
            try:
                json_data = json.loads(data)
                # Handle common API response structures
                if isinstance(json_data, dict):
                    # Check for common field names
                    for key in ['ip', 'IP', 'address', 'Address', 'public_ip', 'ip_address']:
                        if key in json_data:
                            value = str(json_data[key])
                            match = re.search(IP_REGEX, value)
                            if match:
                                return match.group()
                    # If no specific field found, try to find IP in the whole JSON string
                    match = re.search(IP_REGEX, data)
                    if match:
                        return match.group()
                else:
                    # If not a dict, search directly in the string
                    match = re.search(IP_REGEX, data)
                    if match:
                        return match.group()
            except json.JSONDecodeError:
                # If not JSON, search directly in the string
                match = re.search(IP_REGEX, data)
                if match:
                    return match.group()

            raise ValueError("No valid IP address found in the API response")

    except urllib.error.URLError as e:
        raise ValueError(f"API request failed: {str(e.reason)}")
    except urllib.error.HTTPError as e:
        raise ValueError(f"API request failed with HTTP error {e.code}: {e.reason}")
    except Exception as e:
        raise ValueError(f"API request failed: {str(e)}")
